  let data=load();let rawMarkets=[],passed=[],rejected=[],combos=[],mode='SAFE',sportChoice='All',lastScan=0,scanning=false,hasScanned=false,seenPass=new Set(),toastTimer=null,editingBetId=null,pendingMarketLink=null;
