      const out=await pool(jobs,6);const events=new Map();let failures=0;for(const chunk of out){if(!chunk||chunk.error){failures++;continue;}for(const ev of chunk.events){const id=ev.id||ev.slug;if(!id)continue;const old=events.get(id);events.set(id,{...old,...ev,_sportGuess:old?._sportGuess||chunk.sport||null});}}
