  function setPill(label,type){$('connectionPill').className='pill '+type;$('connectionPill').innerHTML='<span class="status-dot"></span>'+escapeHTML(label);}
  function sportFor(event,raw){if(event._sportGuess)return displaySport(event._sportGuess);let text=[event.sport,event.sportsCategory,event.league,event.category,event.series?.[0]?.slug,event.series?.[0]?.title,(event.tags||[]).map(t=>t.slug||t.label).join(' ')].filter(Boolean).join(' ').toLowerCase();for(const key of Object.keys(sportAliases).sort((a,b)=>b.length-a.length)){if(new RegExp('(^|[^a-z])'+key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z]|$)').test(text))return sportAliases[key];}return displaySport(raw||'Other');}
  function matchStart(event,m){return iso(event.gameStartTime||m.gameStartTime||event.sportsStartTime||m.sportsStartTime||event.startTime||event.game?.startTime||event.eventStartTime||null);}
