  const winnerTerms=/\b(vs\.?|versus|winner|moneyline|match result|to win|who wins|\bv\b)\b/i;
  function determineMeta(event,m,sport){const q=[event.title||'',m.question||'',m.sportsMarketType||''].join(' ');const mt=String(m.sportsMarketType||m.marketType||'').toLowerCase();if(against.test(m.question||'')||/spread|total|over_under|handicap|tournament/.test(mt))return 'Not a match-winner moneyline';if((sport==='Soccer')&&(event.negRisk||parseJSONArray(m.outcomes).includes('Draw')))return 'Soccer 3-way/draw market excluded';if(!(/moneyline|winner|match/.test(mt)||winnerTerms.test(q)))return 'Not an identifiable head-to-head winner market';return null;}
  function gammaPrice(m,index){const a=parseJSONArray(m.outcomePrices);return num(a[index]);}
