        result.push({id:'gamma-reject-'+String(m.id||uid()),matchId:'event-'+String(ev.id||ev.slug),sport,league,teams:labels.slice(0,2),prices:prices.slice(0,2),liquidity:gammaLiquidity(m,ev),spread:gammaSpread(m),start,live:isLive(ev,m),open:openMarket(ev,m),url:goodURL('https://polymarket.com/event/'+ev.slug),source:'gamma',technicalReject:'Three-way winner market includes draw; rejected by two-outcome rule'});
