  function renderCombos(){document.querySelectorAll('.mode-card').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('stakePreview').textContent=money(data.settings.staking==='branch'?data.settings.branchStake:data.settings.flatStake);$('stakeModePreview').textContent=data.settings.staking==='branch'?'Branch starting stake · manual':'Flat staking';combos=comboCandidates();$('comboResults').innerHTML=combos.length?combos.map((c,i)=>comboHTML(c,i)).join(''):`<div class="empty-state"><div class="empty-icon">◇</div><h3>No ${mode} combos meet your rules</h3><p>Need at least two different qualifying matches${mode==='SAFE'?' with HIGH execution-data quality':''}. Expand your time window or check the Rejected list. Do not lower thresholds just to force picks.</p></div>`;}
