  function sparkChart(points){if(!points?.length)return '<div class="chart-empty">Add and settle wagers to see chart data</div>';const W=500,H=160,pad=12,values=points.map(v=>Number(v)),lo=Math.min(...values),hi=Math.max(...values),range=Math.max(1,hi-lo),pts=values.map((v,i)=>`${pad+(i/(values.length-1||1))*(W-2*pad)},${H-pad-((v-lo)/range)*(H-2*pad)}`),line=pts.join(' '),fill=`${pts[0]} ${line} ${W-pad},${H-pad} ${pad},${H-pad}`;return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Bankroll history"><defs><linearGradient id="chartShade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#6df4c2" stop-opacity=".27"/><stop offset="1" stop-color="#6df4c2" stop-opacity="0"/></linearGradient></defs><line x1="0" y1="${H-12}" x2="${W}" y2="${H-12}" stroke="#2b4058"/><polygon points="${fill}" fill="url(#chartShade)"/><polyline points="${line}" fill="none" stroke="#6df4c2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="12" y="14" fill="#acc8cc" font-size="12">${escapeHTML(money(hi))}</text><text x="12" y="${H-20}" fill="#8fa4bb" font-size="12">${escapeHTML(money(lo))}</text></svg>`;}
  function weeklyChart(){const map=new Map();for(const b of data.bets.filter(x=>x.status!=='pending')){const d=new Date(b.settledAt||b.date),monday=new Date(d);monday.setDate(d.getDate()-((d.getDay()+6)%7));const key=monday.toISOString().slice(0,10);map.set(key,(map.get(key)||0)+pnl(b));}const entries=[...map.entries()].sort().slice(-8);if(!entries.length)return '<div class="chart-empty">No settled weeks yet</div>';const max=Math.max(1,...entries.map(x=>Math.abs(x[1])));return `<svg viewBox="0 0 500 165" role="img" aria-label="Weekly profit and loss"><line x1="0" y1="80" x2="500" y2="80" stroke="#496078" stroke-dasharray="3,3"/>${entries.map(([week,value],i)=>{const width=500/entries.length-15,x=i*500/entries.length+8,h=65*Math.abs(value)/max,y=value>=0?80-h:80;return `<rect x="${x}" y="${y}" width="${width}" height="${Math.max(h,1)}" rx="4" fill="${value>=0?'#63eabd':'#f27b8f'}"/><text x="${x+width/2}" y="${value>=0?y-5:y+h+13}" fill="#d7e7f5" font-size="10" text-anchor="middle">${escapeHTML(money(value))}</text><text x="${x+width/2}" y="159" fill="#8ea7bd" font-size="10" text-anchor="middle">${escapeHTML(week.slice(5))}</text>`;}).join('')}</svg>`;}
