    function node(n,depth=0){if(depth>210)return'';const children=data.branches.filter(x=>x.parentId===n.id);return `<div class="tree-node"><div class="branch-content"><div><strong>Level ${n.level} · ${money(n.amount)}</strong><span class="badge ${n.status==='unplaced'?'blue':badgeStatus(n.status)}">${escapeHTML(n.status.toUpperCase())}</span></div><div style="margin-top:7px"><span>Gross payout ${money(n.payout||0)}${n.betId?' · Linked wager':''}</span>${n.status==='unplaced'?`<button class="ghost-btn small" data-action="placebranch" data-id="${escapeHTML(n.id)}">Log wager</button>`:''}</div></div><div class="branch-children">${children.map(x=>node(x,depth+1)).join('')}</div></div>`;}
